@@ -0,0 +1,67 @@
+"use client";
+
+import * as React from "react";
+import { useTransition } from "react";
+import { Heart } from "lucide-react";
+import { addFavorite, removeFavorite } from "@/app/(customer)/account/actions";
+import { t } from "@/lib/i18n";
+import { useToast } from "@/components/ui/Toast";
+
+/**
+ * Heart toggle to save/remove a listener. Keyboard-operable, state via
+ * aria-pressed (text label in aria-label, never colour alone), announced.
+ */
+export function FavoriteButton({
+  providerId,
+  providerName,
+  initialFavorite,
+}: {
+  providerId: string;
+  providerName: string;
+  initialFavorite: boolean;
+}) {
+  const [favorite, setFavorite] = React.useState(initialFavorite);
+  const [pending, startTransition] = useTransition();
+  const { announce } = useToast();
+
+  function toggle() {
+    const next = !favorite;
+    setFavorite(next);
+    startTransition(async () => {
+      const res = next
+        ? await addFavorite(providerId)
+        : await removeFavorite(providerId);
+      if (!res.ok) {
+        setFavorite(!next); // revert
+        return;
+      }
+      announce(
+        next
+          ? t("favorite.added", { name: providerName })
+          : t("favorite.removed", { name: providerName }),
+      );
+    });
+  }
+
+  return (
+    <button
+      type="button"
+      onClick={toggle}
+      disabled={pending}
+      aria-pressed={favorite}
+      aria-label={
+        favorite
+          ? t("favorite.remove", { name: providerName })
+          : t("favorite.add", { name: providerName })
+      }
+      className="inline-flex size-11 items-center justify-center rounded-pill border border-border-strong bg-surface text-ink-soft hover:bg-primary-tint/50 aria-pressed:border-accent aria-pressed:text-accent"
+    >
+      <Heart
+        size={20}
+        strokeWidth={2}
+        aria-hidden="true"
+        className={favorite ? "fill-accent" : ""}
+      />
+    </button>
+  );
+}
