@@ -0,0 +1,47 @@
+"use client";
+
+import * as React from "react";
+import { useTransition } from "react";
+import { Button } from "@/components/ui/Button";
+import { Field, Input } from "@/components/ui/Field";
+import { updateProfileName } from "@/app/(customer)/account/actions";
+import { t } from "@/lib/i18n";
+import { useToast } from "@/components/ui/Toast";
+
+export function NameSettingForm({ initialName }: { initialName: string }) {
+  const [name, setName] = React.useState(initialName);
+  const [pending, startTransition] = useTransition();
+  const [error, setError] = React.useState<string | null>(null);
+  const { toast } = useToast();
+
+  function save() {
+    setError(null);
+    startTransition(async () => {
+      const res = await updateProfileName(name);
+      if (!res.ok) {
+        setError(res.error ?? t("auth.errorGeneric"));
+        return;
+      }
+      toast(t("account.nameSaved"), "success");
+    });
+  }
+
+  return (
+    <div className="flex flex-wrap items-end gap-3">
+      <Field label={t("account.yourNameLabel")} error={error ?? undefined} required>
+        {(p) => (
+          <Input
+            {...p}
+            value={name}
+            onChange={(e) => setName(e.target.value)}
+            maxLength={120}
+            autoComplete="name"
+          />
+        )}
+      </Field>
+      <Button onClick={save} disabled={pending}>
+        {pending ? t("ui.loading") : t("account.saveName")}
+      </Button>
+    </div>
+  );
+}
