+"use client";
+
+import * as React from "react";
+import Link from "next/link";
+import { DataTable, type Column } from "@/components/ui/DataTable";
+import { formatCents } from "@/lib/format";
+import { t } from "@/lib/i18n";
+
+export interface PastSessionRow {
+  id: string;
+  bookingId: string;
+  dateLabel: string;
+  endedAtMs: number;
+  listenerName: string;
+  durationLabel: string;
+  amountCents: number;
+  hasReview: boolean;
+}
+
+export function PastSessionsTable({ rows }: { rows: PastSessionRow[] }) {
+  const columns: Column<PastSessionRow>[] = [
+    {
+      key: "dateLabel",
+      header: t("account.colDate"),
+      sortable: true,
+      sortValue: (r) => r.endedAtMs,
+    },
+    { key: "listenerName", header: t("account.colListener") },
+    { key: "durationLabel", header: t("account.colDuration") },
+    {
+      key: "amountCents",
+      header: t("account.colAmount"),
+      align: "right",
+      sortable: true,
+      sortValue: (r) => r.amountCents,
+      render: (r) => formatCents(r.amountCents),
+    },
+    {
+      key: "actions",
+      header: t("account.colActions"),
+      render: (r) => (
+        <span className="flex flex-wrap gap-3">
+          {!r.hasReview ? (
+            <Link
+              href={`/session/${r.bookingId}/summary`}
+              className="font-bold text-primary underline underline-offset-[3px]"
+            >
+              {t("account.leaveReview")}
+            </Link>
+          ) : null}
+          <a
+            href={`/account/receipt/${r.bookingId}`}
+            className="font-bold text-primary underline underline-offset-[3px]"
+          >
+            {t("account.seeReceipt")}
+          </a>
+        </span>
+      ),
+    },
+  ];
+
+  return (
+    <DataTable
+      caption={t("account.pastCaption")}
+      columns={columns}
+      rows={rows}
+      getRowKey={(r) => r.id}
+      emptyText={t("account.pastNone")}
+    />
+  );
+}
