10	export interface FieldProps {
11	  id?: string;
12	  label: string;
13	  /** Optional helper text shown under the label, tied via aria-describedby. */
14	  hint?: string;
15	  /** Error message; when set, the field is marked invalid and described by it. */
16	  error?: string;
17	  required?: boolean;
18	  children: (props: {
19	    id: string;
20	    "aria-describedby"?: string;
21	    "aria-invalid"?: boolean;
22	    "aria-required"?: boolean;
23	  }) => React.ReactNode;
24	}
25	
26	/**
27	 * Field wrapper: a real <label> tied to its control, optional hint and error,
28	 * wired through aria-describedby / aria-invalid. Use with <Input>/<Select>.
29	 */
30	export function Field({
31	  id,
32	  label,
33	  hint,
34	  error,
35	  required,
36	  children,
37	}: FieldProps) {
38	  const fieldId = useFieldId(id);
39	  const hintId = hint ? `${fieldId}-hint` : undefined;
40	  const errorId = error ? `${fieldId}-error` : undefined;
41	  const describedBy = [hintId, errorId].filter(Boolean).join(" ") || undefined;
42	
43	  return (
44	    <div className="flex flex-col gap-1.5">
45	      <label htmlFor={fieldId} className="text-base font-bold text-ink">
46	        {label}
47	        {required ? (
48	          <span className="font-normal text-ink-soft">
49	            {" "}
50	            ({t("ui.required")})
51	          </span>
52	        ) : null}
53	      </label>
54	      {hint ? (
55	        <p id={hintId} className="text-sm text-ink-soft">
56	          {hint}
57	        </p>
58	      ) : null}
59	      {children({
60	        id: fieldId,
61	        "aria-describedby": describedBy,
62	        "aria-invalid": error ? true : undefined,
63	        "aria-required": required || undefined,
64	      })}
65	      {error ? (
66	        <p id={errorId} className="text-sm font-semibold text-alert" role="alert">
67	          {error}
68	        </p>
69	      ) : null}
70	    </div>
71	  );
72	}
